import { useEffect, useMemo, useRef, useState } from "react";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import {
  reviewsActions,
  statsOf,
  getServerReviews,
  getProductReviews,
  submitStoreReview,
  submitProductReview,
  catalogKeyFor,
  STORE_KEY_HOME,
  STORE_KEY_PERFUMES,
  STORE_KEY_OUDS,
  STORE_KEY_INCENSE,
  STORE_KEY_MISTS,
  STORE_KEY_LOTIONS,
  STORE_KEY_MUKHAMARIA,
  STORE_KEY_HAIR,
  mergeUnique,
  savePendingReview,
  readPendingReview,
  clearPendingReview,
  tokenUsable,
  selectServerComments,
  selectProductComments
} from "../../redux/slices/reviewsSlice.js";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { PATHS, productPath } from "../../routes.js";
import { validateReview, isPlaceholderName } from "../../validation.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { atyabLog } from "../../redux/api.js";
import { productName, tr2 } from "../../i18n.js";
import { Icon } from "../Source/Icons.jsx";
import { Stars } from "../Source/Money.jsx";
import UserComment from "./UserComment.jsx";

const PAGE_SIZE = 5;
const EMPTY_OWN = [];

function group(n) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function CommentCard(props) {
  return (
    <UserComment
      comment={props.c}
      lang={props.language}
      meta={props.meta}
      helpfulOn={props.helpfulIds.indexOf(props.c.id) !== -1}
      onHelpful={props.onHelpful}
    />
  );
}

export default function UserRate(props) {
  const dispatch = useAppDispatch();
  const channelKey = props.channelKey;
  const product = props.product || null;
  const productId = product ? Number(product.id) || 0 : 0;
  const mode = props.display || (product ? "paged" : "marquee");
  const isMarquee = mode === "marquee";
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const isBakhoor = !!(product && product.kindLabel) || props.noun === "بخور";
  const noun = tr2(language, isBakhoor ? "bakhoor" : "perfume", isBakhoor ? "بخور" : "عطر");
  const name = product ? productName(product, language) : "";
  /* ★ المسجّل يقيّم باسمه تلقائياً — لا حقل اسم له */
  const accountName = useAppSelector(function (s) {
    const p = (s.user && s.user.profile) || {};
    const full = [p.firstName, p.lastName].filter(Boolean).join(" ").trim();
    if (full && !isPlaceholderName(full)) return full;
    const d = (s.customer && s.customer.details) || {};
    const dfull = [d.firstName, d.lastName].filter(Boolean).join(" ").trim();
    if (dfull && !isPlaceholderName(dfull)) return dfull;
    return "";
  });

  const own = useAppSelector(function (s) {
    return s.reviews.own[channelKey] || EMPTY_OWN;
  });
  const serverChannel = useAppSelector(function (s) {
    return productId ? EMPTY_OWN : selectServerComments(s, channelKey);
  });
  const serverProduct = useAppSelector(function (s) {
    return productId ? selectProductComments(s, productId) : EMPTY_OWN;
  });
  const server = productId ? serverProduct : serverChannel;

  useEffect(
    function () {
      if (productId) {
        /* ★ v17-S1: تعليقات المنتج force عند كل زيارة (dedupe للمتزامن) */
        const thunk = getProductReviews(productId, { force: true });
        if (thunk) dispatch(thunk);
      } else {
        const thunk = getServerReviews(channelKey);
        if (thunk) dispatch(thunk);
      }
    },
    [dispatch, channelKey, productId]
  );

  const [page, setPage] = useState(1);
  const [helpfulIds, setHelpfulIds] = useState([]);
  const [form, setForm] = useState({ name: "", rating: 0, text: "" });
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();
  const location = useLocation();
  const publishedRef = useRef(false);

  /* ★ عودة من الدخول ومسودة بانتظار هذا المكان؟ تُنشر تلقائياً مرة واحدة */
  useEffect(
    function () {
      if (publishedRef.current) return;
      let d = null;
      try { d = readPendingReview(); } catch (e) { d = null; }
      if (!d || d.rating == null || !d.text) return;
      if (!tokenUsable()) return;
      const match = d.productId
        ? Number(d.productId) === productId
        : !productId && String(d.key || "") === String(channelKey);
      if (!match) return;
      publishedRef.current = true;
      const action = d.productId
        ? submitProductReview({ productId: Number(d.productId), rating: d.rating, title: "", text: d.text })
        : submitStoreReview({ key: channelKey, catalogKey: String(d.catalogKey || catalogKeyFor(channelKey, props.catalogKey)), rating: d.rating, title: "", text: d.text });
      dispatch(action).unwrap().then(function () {
        clearPendingReview();
        dispatch(uiActions.toastShown("تم نشر تقييمك — شكراً لك"));
      }, function () {
        publishedRef.current = false;
      });
    },
    [dispatch, channelKey, productId, props.catalogKey]
  );

  useEffect(
    function () {
      setPage(1);
    },
    [channelKey, productId]
  );

  const comments = useMemo(
    function () {
      return mergeUnique(own, server);
    },
    [own, server]
  );

  const stats = useMemo(
    function () {
      return statsOf(comments);
    },
    [comments]
  );

  const seedAvg = Number(props.seedAverage) || Number((product && product.rating) || 0) || 0;
  const seedTotal = Math.round(Number(props.seedTotal) || Number((product && product.reviews) || 0) || 0);
  const shownTotal = comments.length ? stats.total : seedTotal;
  const shown = useMemo(
    function () {
      if (comments.length) return stats;
      if (!seedTotal || !seedAvg) return stats;
      const weights = [5, 4, 3, 2, 1].map(function (s) {
        const d = Math.abs(s - seedAvg);
        return d >= 2 ? 0.04 : Math.pow(2 - d, 2);
      });
      const wsum = weights.reduce(function (a, b) { return a + b; }, 0) || 1;
      const dist = weights.map(function (w) { return Math.round((w / wsum) * seedTotal); });
      let drift = seedTotal - dist.reduce(function (a, b) { return a + b; }, 0);
      let guard = 0;
      while (drift !== 0 && guard++ < 20) {
        const at = [5, 4, 3, 2, 1].reduce(function (best, s, i) {
          return Math.abs(s - seedAvg) < Math.abs([5, 4, 3, 2, 1][best] - seedAvg) ? i : best;
        }, 0);
        dist[at] += drift > 0 ? 1 : -1;
        drift += drift > 0 ? -1 : 1;
      }
      return {
        dist: dist,
        total: seedTotal,
        average: seedAvg,
        percent: dist.map(function (n) { return seedTotal ? Math.round((n / seedTotal) * 100) : 0; })
      };
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [comments.length, seedAvg, seedTotal]
  );

  const line = useMemo(
    function () {
      if (product) {
        return (
          group(product.reviews || shownTotal) +
          " " +
          tr2(language, "reviews", "تقييماً") +
          " · " +
          group(product.sales || 0) +
          " " +
          tr2(language, "purchases", "عملية شراء")
        );
      }
      if (props.catalogKey === "incense") {
        return group(props.itemsCount || 0) + " " + tr2(language, "bakhoor products", "منتجاً في قسم البخور");
      }
      /* ★ R23: صيغ العدّ للأقسام الجديدة — وإلا ظهر «عطراً في المتجر» */
      if (props.catalogKey === "ouds") {
        return group(props.itemsCount || 0) + " " + tr2(language, "oud oils", "دهن عود");
      }
      if (props.catalogKey === "mists") {
        return group(props.itemsCount || 0) + " " + tr2(language, "mists", "مرشات");
      }
      if (props.catalogKey === "lotions") {
        return group(props.itemsCount || 0) + " " + tr2(language, "lotions", "لوشنات");
      }
      if (props.catalogKey === "mukhamaria") {
        return group(props.itemsCount || 0) + " " + tr2(language, "mukhamaria", "مخمريات");
      }
      if (props.catalogKey === "hair") {
        return group(props.itemsCount || 0) + " " + tr2(language, "hair perfumes", "عطور شعر");
      }
      return group(props.itemsCount || 0) + " " + tr2(language, "perfumes in the store", "عطراً في المتجر");
    },
    [product, props.catalogKey, props.itemsCount, shownTotal, language]
  );

  function submit() {
    const effectiveName = accountName || form.name;
    const result = validateReview({ name: effectiveName, rating: form.rating, text: form.text });
    setErrors(result.errors);
    if (!result.valid) {
      dispatch(uiActions.toastShown(result.firstError));
      return;
    }
    dispatch(
      reviewsActions.addComment({
        key: channelKey,
        name: effectiveName,
        rating: form.rating,
        text: form.text
      })
    );
    /* ★ محلياً فوراً + نشر للخادم في الخلفية: صفحة كتالوج → store مع catalogKey،
       صفحة منتج → product/{id}. غير المسجّل يحتفظ بتقييمه محلياً فقط. */
    const snapshot = { rating: form.rating, text: form.text };
    setForm({ name: "", rating: 0, text: "" });
    setPage(1);
    /* ★ ضيف؟ المسودة تُحفظ ويُوجَّه للدخول مع عودة لنفس المكان — والنشر تلقائي بعدها */
    if (!tokenUsable()) {
      if (productId) savePendingReview({ productId: productId, rating: snapshot.rating, text: snapshot.text });
      else savePendingReview({ key: channelKey, catalogKey: catalogKeyFor(channelKey, props.catalogKey), rating: snapshot.rating, text: snapshot.text });
      dispatch(uiActions.toastShown("سجّل الدخول لنشر تقييمك — مسودتك محفوظة"));
      try {
        navigate(PATHS.login, { state: { from: product ? productPath(product.id) : location.pathname } });
      } catch (e) {}
      return;
    }
    function onPosted() {
      dispatch(uiActions.toastShown("تم نشر تقييمك — شكراً لك"));
    }
    function onPostFail(err) {
      if (err && (err.status === 401 || err.status === 403)) {
        dispatch(uiActions.toastShown("حُفظ تقييمك على هذا الجهاز — سجّل الدخول لنشره للجميع"));
      } else {
        /* ★ صامت للعميل (تقييمه محفوظ محلياً ظاهر) — والسطر للتشخيص:
           405 مثلاً = مسار النشر في الباك-اند يحتاج مراجعة */
        atyabLog("reviews POST failed", err && err.status, err && err.message);
      }
    }
    if (productId) {
      dispatch(submitProductReview({ productId: productId, rating: snapshot.rating, title: "", text: snapshot.text })).unwrap().then(onPosted, onPostFail);
    } else {
      dispatch(submitStoreReview({ key: channelKey, catalogKey: catalogKeyFor(channelKey, props.catalogKey), rating: snapshot.rating, title: "", text: snapshot.text })).unwrap().then(onPosted, onPostFail);
    }
  }

  /* ★ R16: تبديل «مفيد» — إعجاب ثم إلغاء (unmarkHelpful ينقص المحلي) */
  function onHelpful(id) {
    if (helpfulIds.indexOf(id) === -1) {
      dispatch(reviewsActions.markHelpful({ key: channelKey, id: id }));
      setHelpfulIds(function (prev) {
        return prev.indexOf(id) === -1 ? prev.concat([id]) : prev;
      });
    } else {
      dispatch(reviewsActions.unmarkHelpful({ key: channelKey, id: id }));
      setHelpfulIds(function (prev) {
        return prev.filter(function (x) { return x !== id; });
      });
    }
  }

  /* ★ R15: بلا تكرار AI («عطر «عطر عطشان»») — إن بدأ الاسم بالنوع
     لا نُضيفه، وبلا «حجم 100 مل» المبهمة لقنوات المتجر */
  function metaFor() {
    if (product) {
      const nm = String(product.name || "");
      if (nm && nm.indexOf(noun) === 0) return tr2(language, productName(product, "en"), nm);
      return tr2(language, noun + " " + productName(product, "en"), noun + " «" + nm + "»");
    }
    if (channelKey === STORE_KEY_INCENSE) return tr2(language, "Bakhoor reviews", "تقييمات البخور");
    if (channelKey === STORE_KEY_OUDS) return tr2(language, "Oud oils reviews", "تقييمات دهن العود");
    /* ★ R23: عناوين قنوات «باقي المنتجات» */
    if (channelKey === STORE_KEY_MISTS) return tr2(language, "Mists reviews", "تقييمات المرشات");
    if (channelKey === STORE_KEY_LOTIONS) return tr2(language, "Lotions reviews", "تقييمات اللوشنات");
    if (channelKey === STORE_KEY_MUKHAMARIA) return tr2(language, "Mukhamaria reviews", "تقييمات المخمريات");
    if (channelKey === STORE_KEY_HAIR) return tr2(language, "Hair perfumes reviews", "تقييمات عطور الشعر");
    if (channelKey === STORE_KEY_PERFUMES || channelKey === STORE_KEY_HOME) return tr2(language, "Store reviews", "تقييمات المتجر");
    return tr2(language, "Store reviews", "تقييمات المتجر");
  }
  const meta = metaFor();

  const totalPages = Math.max(1, Math.ceil(comments.length / PAGE_SIZE));
  const safePage = Math.min(Math.max(1, page), totalPages);
  const paged = comments.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);
  /* ★ التعليق على المنتج فقط — الصفحات عرض بلا نموذج (قابل للتجاوز عبر allowSubmit) */
  const canSubmit = props.allowSubmit != null ? !!props.allowSubmit : !!product;

  function pageNumbers() {
    const out = [];
    if (totalPages <= 7) {
      for (let i = 1; i <= totalPages; i++) out.push(i);
      return out;
    }
    out.push(1);
    if (safePage > 3) out.push("…");
    for (let i = Math.max(2, safePage - 1); i <= Math.min(totalPages - 1, safePage + 1); i++) out.push(i);
    if (safePage < totalPages - 2) out.push("…");
    out.push(totalPages);
    return out;
  }

  return (
    <div className={"rd" + (isMarquee ? " rd-marquee-mode" : " rd-paged-mode")} id="productRate">
      <div className="rd-summary">
        <div className="rd-score">
          <b>{shown.average.toFixed(1)}</b>
          <div className="rd-score-side">
            <Stars rating={shown.average} className="rd-stars" />
            <small>{line}</small>
          </div>
        </div>
        <div className="rd-bars">
          {shown.dist.map(function (count, i) {
            const stars = 5 - i;
            return (
              <div className="rd-bar" key={stars}>
                <span className="rd-bar-k">{stars} ★</span>
                <span className="rd-bar-track">
                  <i style={{ width: shown.percent[i] + "%" }} />
                </span>
                <span className="rd-bar-v">{group(count)}</span>
              </div>
            );
          })}
        </div>
      </div>

      {canSubmit ? (
      <form
        className="rd-form"
        noValidate
        onSubmit={function (e) {
          e.preventDefault();
          submit();
        }}
      >
        <h3>
          <Icon name="star" fill="currentColor" strokeWidth={0} />
          <span>{props.formTitle || tr2(language, "Your opinion matters", "رأيك يهمنا")}</span>
        </h3>

        <div className="rd-form-row">
          {accountName ? (
            <div className="rd-field">
              <span className="rd-label">{tr2(language, "Reviewing as", "تقيّم باسم")}</span>
              <b className="rd-as">{accountName}</b>
            </div>
          ) : (
            <label className="rd-field">
              <span className="rd-label">{tr2(language, "Your name (or nickname)", "اسمك (أو لقبك)")}</span>
              <input
                className={"rd-input" + (errors.name ? " is-bad" : "")}
                type="text"
                value={form.name}
                maxLength={40}
                placeholder={tr2(language, "e.g. Abdullah", "مثال: عبدالله")}
                onChange={function (e) {
                  setForm(Object.assign({}, form, { name: e.target.value }));
                }}
              />
            </label>
          )}

          <div className="rd-field">
            <span className="rd-label">{tr2(language, "Your rating", "تقييمك")}</span>
            <div className="rd-picker" role="group" aria-label={tr2(language, "Choose the number of stars", "اختر عدد النجوم")}>
              {[1, 2, 3, 4, 5].map(function (n) {
                return (
                  <button
                    key={n}
                    className={"rd-pick" + (form.rating >= n ? " is-on" : "")}
                    type="button"
                    aria-label={tr2(language, n + " of 5", n + " من 5")}
                    aria-pressed={form.rating === n ? "true" : "false"}
                    onClick={function () {
                      setForm(Object.assign({}, form, { rating: n }));
                      setErrors(Object.assign({}, errors, { rating: "" }));
                    }}
                  >
                    <Icon name="star" fill="currentColor" strokeWidth={0} />
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* ★ R16: بلا سطر زائد — اسم المنتج مطويّ في placeholder بدل عنوان مكرر */}
        <label className="rd-field">
          <textarea
            className={"rd-textarea" + (errors.text ? " is-bad" : "")}
            rows={3}
            maxLength={800}
            value={form.text}
            placeholder={
              product
                ? tr2(language, "Share your honest review of «" + productName(product, "en") + "»…", "شاركنا رأيك بصراحة في «" + product.name + "»…")
                : tr2(language, "Share your honest opinion about Atyab Al Jasem…", "شاركنا رأيك بصراحة عن أطياب الجاسم…")
            }
            onChange={function (e) {
              setForm(Object.assign({}, form, { text: e.target.value }));
            }}
          />
        </label>

        <div className="rd-form-actions">
          <button className="btn-primary rd-submit" type="submit">
            <Icon name="send" strokeWidth={1.8} />
            <span>{tr2(language, "Send review", "أرسل التقييم")}</span>
          </button>
          <span className="rd-form-note">
            <Icon name="lock" strokeWidth={1.7} />
            كلمتك أمانة — قيّم بعدل، فتقييمك يظهر للجميع باسمك.
          </span>
        </div>
      </form>
      ) : (
        <p className="rd-submit-note">
          <Icon name="info" strokeWidth={1.7} />
          <span>التقييم يُكتب من صفحة المنتج نفسه — <Link to={PATHS.perfumes}>اختر منتجاً وشاركنا رأيك</Link>.</span>
        </p>
      )}

      {isMarquee ? (
        <div className="rd-marquee" dir="ltr">
          {comments.length === 0 ? (
            <p className="rd-empty">كن أول من يقيّم — رأيك يهمنا.</p>
          ) : (
            <div className="rd-marquee-track">
              {[0, 1].map(function (copy) {
                return (
                  <ul className="rd-marquee-half rd-list" dir="rtl" key={copy} aria-hidden={copy === 1 ? "true" : undefined}>
                    {comments.map(function (c) {
                      return (
                        <CommentCard key={String(c.id) + "-" + copy} c={c} language={language} meta={meta} helpfulIds={helpfulIds} onHelpful={onHelpful} />
                      );
                    })}
                  </ul>
                );
              })}
            </div>
          )}
        </div>
      ) : (
        <>
          {comments.length === 0 ? (
            <p className="rd-empty">لا توجد تقييمات بعد — كن أول من يقيّم هذا المنتج.</p>
          ) : (
            <ul className="rd-list">
              {paged.map(function (c) {
                return (
                  <CommentCard key={c.id} c={c} language={language} meta={meta} helpfulIds={helpfulIds} onHelpful={onHelpful} />
                );
              })}
            </ul>
          )}
          {totalPages > 1 ? (
            <nav className="rd-pager" aria-label="صفحات التقييمات">
              <button
                className="rd-page-nav"
                type="button"
                disabled={safePage <= 1}
                onClick={function () { setPage(safePage - 1); }}
              >
                السابق
              </button>
              {pageNumbers().map(function (n, i) {
                if (n === "…") return <span className="rd-page-gap" key={"g" + i}>…</span>;
                return (
                  <button
                    key={n}
                    type="button"
                    className={"rd-page-num" + (n === safePage ? " is-on" : "")}
                    aria-current={n === safePage ? "page" : undefined}
                    onClick={function () { setPage(n); }}
                  >
                    {n}
                  </button>
                );
              })}
              <button
                className="rd-page-nav"
                type="button"
                disabled={safePage >= totalPages}
                onClick={function () { setPage(safePage + 1); }}
              >
                التالي
              </button>
            </nav>
          ) : null}
        </>
      )}
    </div>
  );
}
