import { memo } from "react";
import { Stars } from "../Source/Money.jsx";
import { Icon } from "../Source/Icons.jsx";

function pick(lang, ar, en) {
  return lang === "en" && en ? en : ar;
}

/* ★ R15/R16: أنيميشن الإعجاب يعمل بطبقتين حتى لا يموت أبداً:
   1) Web Animations (JS) على الزر والإبهام — لا يمرّ بـCSS ولا يتأثر
      بقاعدة html:not(.ready) ولا بإعداد «تقليل الحركة».
   2) كلاس is-pop (CSS keyframes) كطبقة ثانية للمتصفحات الكاملة.
   ★ عدّاد تقييمات الخادم: markHelpful يزيد المحلية فقط، لذلك نعرض
   +1 لضغطة المستخدم على تقييمات الخادم (srv-/fb-) حتى يرى الأثر فوراً.
   ★ R16: الزر تبديل — ضغطة تُعجب وضغطة تُلغي (الأب يقلب helpfulIds). */
function popBtn(btn) {
  if (!btn) return;
  try {
    btn.classList.remove("is-pop");
    void btn.offsetWidth;
    btn.classList.add("is-pop");
    window.setTimeout(function () {
      try {
        btn.classList.remove("is-pop");
      } catch (err) {}
    }, 600);
  } catch (err) {}
  try {
    if (btn.animate) {
      btn.animate(
        [
          { transform: "scale(1)" },
          { transform: "scale(1.14)", offset: 0.4 },
          { transform: "scale(1)", offset: 1 }
        ],
        { duration: 420, easing: "ease-out" }
      );
      const svg = btn.querySelector("svg");
      if (svg && svg.animate) {
        svg.animate(
          [
            { transform: "scale(1) rotate(0deg)" },
            { transform: "scale(1.7) rotate(-16deg)", offset: 0.35 },
            { transform: "scale(0.9) rotate(8deg)", offset: 0.65 },
            { transform: "scale(1) rotate(0deg)", offset: 1 }
          ],
          { duration: 480, easing: "ease-out" }
        );
      }
    }
  } catch (err) {}
}

function UserComment(props) {
  const c = props.comment;
  if (!c) return null;
  const lang = props.lang || "ar";
  const name = pick(lang, c.name, c.nameEn);
  const date = pick(lang, c.date, c.dateEn);
  const text = pick(lang, c.text, c.textEn);
  const reply = pick(lang, c.reply, c.replyEn);
  const isOwn = String((c && c.id) || "").indexOf("own-") === 0;
  const shownHelpful = (Number(c.helpful) || 0) + (!isOwn && props.helpfulOn ? 1 : 0);

  return (
    <li className="rd-card rd-card--person" hidden={!!props.hidden}>
      <div className="rd-who" data-no-i18n>
        <span className="rd-avatar" aria-hidden="true">
          {String(name || "؟").charAt(0)}
        </span>
        <b className="rd-name">
          {name}
        </b>
        {c.verified ? <span className="rd-verified">شراء موثّق</span> : null}
        <span className="rd-date">
          {date}
        </span>
      </div>

      <Stars rating={c.rating} className="rd-stars" rowClass="rd-stars-row" baseClass="rd-stars-base" fillClass="rd-stars-fill" />

      <p className="rd-text" data-no-i18n>
        {text}
      </p>

      {reply ? (
        <div className="rd-reply">
          <b>ردّ أطياب الجاسم:</b> <span data-no-i18n>{reply}</span>
        </div>
      ) : null}

      <div className="rd-foot">
        <button
          className={"rd-helpful" + (props.helpfulOn ? " is-on" : "")}
          type="button"
          aria-pressed={props.helpfulOn ? "true" : "false"}
          onClick={function (e) {
            /* ★ R16: تبديل — إعجاب ثم إلغاء، كل ضغطة بحركتها */
            if (e && e.currentTarget) popBtn(e.currentTarget);
            if (props.onHelpful) props.onHelpful(c.id);
          }}
        >
          <Icon
            name="thumb"
            strokeWidth={1.7}
          />
          <span>
            مفيد <span className="rd-help-n">({shownHelpful})</span>
          </span>
        </button>
        {props.meta ? <span className="rd-meta">{props.meta}</span> : null}
      </div>
    </li>
  );
}

export default memo(UserComment);
